'use client'

import { useState } from 'react'

export default function Home() {
  const [count, setCount] = useState(0)

  return (
    <main className="app">
      <h1>Next.js 16 App</h1>
      <button onClick={() => setCount((v) => v + 1)}>Count is {count}</button>
    </main>
  )
}

